using HakutaiKagami.Core.World;
namespace HakutaiKagami.Core.Contracts;
public sealed record FieldPoint(long X,long Y);
public sealed record FieldLeg(FieldPoint From,FieldPoint To,long StartAt,long EndAt,int Speed,string Terrain);
public sealed record FieldRoute(EntityId Unit,FieldPoint Goal,FieldLeg[] Legs);
public sealed record FieldRequest(EntityId Id,EntityId Actor,FieldPoint A,FieldPoint B);
public sealed record FieldOrder(FieldRequest Request,long At,FieldRoute[] Routes);
public sealed record FieldState(FieldOrder[] Orders);
public sealed record FieldUnitView(EntityId Unit,FieldPoint Position,FieldPoint Next,bool Moving,long Distance,string Terrain);
// Synthetic 160m patch anchored in the same projected world at Kiyosu. No second clock.
public static class FieldWorld
{
 public const string Ruleset="national-land-field-v1";
 public static string Version{get;}=ContractJson.CanonicalHash(new[]{TrafficWorld.Version,ContractJson.CanonicalHash(Enumerable.Range(-6,16).SelectMany(x=>Enumerable.Range(-6,16).Select(y=>$"{x}/{y}/{Terrain(x,y)}/{Speed(Terrain(x,y))}")).ToArray()),"terrain16x16-10m-cells-v1","road2000-grass1000-forest500-slope400-water-cliff0-v1","continuous-line-slots-cardinal-no-corner-cut-v1"});
 public static bool Enabled(ContractWorld w)=>w.Definitions.Ruleset==Ruleset||RegionalBattle.Enabled(w);
 public static EntityId[] UnitIds=>[new("unit:officer"),new("unit:field-left"),new("unit:field-right")];
 public static FieldPoint Initial(int i)=>new(5000,5000+(i==0?0:i==1?10000:-10000));
 public static string Terrain(int x,int y)=>x< -6||x>9||y< -6||y>9?"outside":x>=8?"water":x==4&&y>=4&&y<=8?"cliff":y==5&&x<4&&x!=0?"water":y==0||x==0?"road":x>=2&&x<=4&&y>=1&&y<=4?"forest":x>=5&&x<=7&&y>=1&&y<=4?"slope":"grass";
 public static int Speed(string terrain)=>terrain switch{"road"=>2000,"grass"=>1000,"forest"=>500,"slope"=>400,_=>0};
 static (int X,int Y) Cell(FieldPoint p)=>((int)Math.Floor(p.X/10000.0),(int)Math.Floor(p.Y/10000.0));
 public static string TerrainAt(FieldPoint p){var c=Cell(p);return Terrain(c.X,c.Y);}
 static FieldPoint Center((int X,int Y)c)=>new(c.X*10000L+5000,c.Y*10000L+5000);
 static long Length(FieldPoint a,FieldPoint b)=>(long)Math.Ceiling(Math.Sqrt((double)(a.X-b.X)*(a.X-b.X)+(double)(a.Y-b.Y)*(a.Y-b.Y)));
 public static FieldLeg[] Plan(FieldPoint from,FieldPoint to,long at){var start=Cell(from);var goal=Cell(to);if(Speed(TerrainAt(from))==0||Speed(TerrainAt(to))==0)throw new InvalidDataException("Impassable terrain");
 var cost=new Dictionary<(int,int),long>{{start,0}};var prev=new Dictionary<(int,int),(int,int)>();var visited=new HashSet<(int,int)>();
 while(true){var candidates=cost.Where(p=>!visited.Contains(p.Key)).OrderBy(p=>p.Value).ThenBy(p=>p.Key.Item1).ThenBy(p=>p.Key.Item2).ToArray();if(candidates.Length==0)throw new InvalidDataException("No terrain route");var q=candidates[0];if(q.Key==goal)break;if(q.Value==0&&visited.Contains(start)||visited.Count>256)throw new InvalidDataException("No terrain route");visited.Add(q.Key);bool any=false;foreach(var delta in new[]{(1,0),(-1,0),(0,1),(0,-1)}){var next=(q.Key.Item1+delta.Item1,q.Key.Item2+delta.Item2);var speed=Speed(Terrain(next.Item1,next.Item2));if(speed==0||visited.Contains(next))continue;var d=q.Value+(5000+Speed(Terrain(q.Key.Item1,q.Key.Item2))-1)/Speed(Terrain(q.Key.Item1,q.Key.Item2))+(5000+speed-1)/speed;if(!cost.TryGetValue(next,out var old)||d<old){cost[next]=d;prev[next]=q.Key;}any=true;}if(!any&&!cost.Any(p=>!visited.Contains(p.Key)))throw new InvalidDataException("No terrain route");}
 var cells=new List<(int,int)>{goal};while(cells[^1]!=start)cells.Add(prev[cells[^1]]);cells.Reverse();var legs=new List<FieldLeg>();void Add(FieldPoint a,FieldPoint b,string terrain){var length=Length(a,b);if(length==0)return;var speed=Speed(terrain);var end=checked(at+(length+speed-1)/speed);legs.Add(new(a,b,at,end,speed,terrain));at=end;}
 Add(from,Center(start),Terrain(start.X,start.Y));for(int i=1;i<cells.Count;i++){var a=Center(cells[i-1]);var b=Center(cells[i]);var mid=new FieldPoint((a.X+b.X)/2,(a.Y+b.Y)/2);Add(a,mid,Terrain(cells[i-1].Item1,cells[i-1].Item2));Add(mid,b,Terrain(cells[i].Item1,cells[i].Item2));}Add(Center(goal),to,Terrain(goal.X,goal.Y));return legs.ToArray();
 }
 public static ContractWorld Create(){var w=TrafficWorld.Create();w.WorldId=new("world:national-land-field-v1");w.Definitions=w.Definitions with{Id=new("scenario:national-land-field-v1"),Ruleset=Ruleset,Version=Version};w.Field=new([]);var u=w.Units.Single(u=>u.Id==new EntityId("unit:officer"));w.Units=w.Units.Select(x=>x.Id==u.Id?x with{Soldiers=40}:x).Concat(new[]{u with{Id=UnitIds[1],Soldiers=30},u with{Id=UnitIds[2],Soldiers=30}}).ToArray();ContractValidation.Validate(w);return w;}
 public static bool Local(ContractWorld w)=>Enabled(w)&&w.Field!.Orders.Length>0&&!(w.Branches!.Journeys.LastOrDefault(j=>j.Actor==w.PlayerControl)?.Legs[0].StartAt>w.Field.Orders[^1].At);
 public static FieldUnitView Sample(ContractWorld w,int i,long at){var order=w.Field!.Orders.LastOrDefault(o=>o.At<=at);if(order==null)return new(UnitIds[i],Initial(i),Initial(i),false,0,TerrainAt(Initial(i)));var r=order.Routes[i];if(r.Legs.Length==0)return new(r.Unit,r.Goal,r.Goal,false,0,TerrainAt(r.Goal));FieldPoint Point(long t){var l=r.Legs.FirstOrDefault(l=>t<l.EndAt)??r.Legs[^1];var n=Math.Clamp(t-l.StartAt,0,l.EndAt-l.StartAt);return new(l.From.X+(l.To.X-l.From.X)*n/(l.EndAt-l.StartAt),l.From.Y+(l.To.Y-l.From.Y)*n/(l.EndAt-l.StartAt));}var p=Point(at);var current=r.Legs.FirstOrDefault(l=>at<l.EndAt);var distance=r.Legs.Sum(l=>at>=l.EndAt?Length(l.From,l.To):at<=l.StartAt?0:Length(l.From,l.To)*(at-l.StartAt)/(l.EndAt-l.StartAt));return new(r.Unit,p,Point(at+1),current!=null,distance,current?.Terrain??TerrainAt(p));}
 static class CoordinateOrigin { internal static readonly RoutePoint Value=NationalRoutes.Nodes.Single(n=>n.Id=="castle").Position; }
 public static RoutePoint ToWorld(FieldPoint p){var origin=CoordinateOrigin.Value;return new(origin.EastMm+p.X-5000,origin.NorthMm+p.Y-5000);}
 public static FieldOrder Prepare(ContractWorld w,FieldRequest request){if(!Enabled(w)||!EntityId.IsValid(request.Id.Value)||request.Actor!=w.PlayerControl||request.A==null||request.B==null||w.Locations.Single(l=>l.Actor==request.Actor).Kind==LocationKind.Traveling||w.Locations.Single(l=>l.Actor==request.Actor).Site is {} site&&site!=ContractFixture.Castle||TravelWorld.Active(w))throw new InvalidDataException("Local formation unavailable");if(w.Requests.Any(r=>r.Id==request.Id)||w.TravelDecisions!.Any(d=>d.Request.Id==request.Id)||w.Actions.Any(a=>a.Actor==request.Actor&&a.Phase==ExecutionPhase.Running))throw new InvalidDataException("Actor busy or request ID used");var permit=ContractFixture.Order("request:field-permit",ActionKind.Move) with{Actor=request.Actor,Executor=request.Actor};if(!WorldSession.Permits(w,request.Actor,permit,w.ElapsedSeconds)||UnitIds.Any(id=>!w.Units.Any(u=>u.Id==id&&u.Commander==request.Actor&&u.Army==new EntityId("army:officer"))))throw new InvalidDataException("Not this officer's force");if(Length(request.A,request.B)<10000)throw new InvalidDataException("Formation line too short");var routes=Enumerable.Range(0,3).Select(i=>{var target=new FieldPoint(request.A.X+(request.B.X-request.A.X)*i/2,request.A.Y+(request.B.Y-request.A.Y)*i/2);return new FieldRoute(UnitIds[i],target,Plan(Sample(w,i,w.ElapsedSeconds).Position,target,w.ElapsedSeconds));}).ToArray();return new(request,w.ElapsedSeconds,routes);}
 public static void Advance(ContractWorld w){if(!Local(w))return;var p=ToWorld(Sample(w,0,w.ElapsedSeconds).Position);var geo=JapanGeography.Inverse(new(p.EastMm,p.NorthMm));w.Locations=w.Locations.Select(l=>l.Actor==w.PlayerControl?(p==NationalRoutes.Nodes.Single(n=>n.Id=="castle").Position?new(l.Actor,LocationKind.AtSite,ContractFixture.Castle,null,0,0,null,null,null,null,w.CommitSequence):new LocationState(l.Actor,LocationKind.AtPosition,null,null,0,0,geo.LatitudeE7,geo.LongitudeE7,0,Version,w.CommitSequence)):l).ToArray();}
 public static long? NextBoundary(ContractWorld w,long target)=>w.Field!.Orders.LastOrDefault()?.Routes.SelectMany(r=>r.Legs).Select(l=>l.EndAt).Where(t=>t>w.ElapsedSeconds&&t<=target).Order().Select(t=>(long?)t).FirstOrDefault();
 public static void Validate(ContractWorld w){var state=w.Field??throw new InvalidDataException("Missing field module");if(state.Orders.Select(o=>o.Request.Id).Distinct().Count()!=state.Orders.Length)throw new InvalidDataException("Duplicate formation command");var replay=ContractJson.Copy(w);replay.Field=new([]);long prior=-1;foreach(var o in state.Orders){if(o.At<0||Length(o.Request.A,o.Request.B)<10000||o.At<prior||o.At>w.ElapsedSeconds||o.Request.Actor!=w.PlayerControl||o.Routes.Length!=3)throw new InvalidDataException("Invalid field order");for(int i=0;i<3;i++){var goal=new FieldPoint(o.Request.A.X+(o.Request.B.X-o.Request.A.X)*i/2,o.Request.A.Y+(o.Request.B.Y-o.Request.A.Y)*i/2);if(o.Routes[i].Unit!=UnitIds[i]||o.Routes[i].Goal!=goal||ContractJson.CanonicalHash(o.Routes[i].Legs)!=ContractJson.CanonicalHash(Plan(Sample(replay,i,o.At).Position,goal,o.At)))throw new InvalidDataException("Formation path/terrain changed");}replay.Field=new([..replay.Field.Orders,o]);prior=o.At;}if(Local(w)){Advance(replay);if(w.Locations.Single(l=>l.Actor==w.PlayerControl)!=(replay.Locations.Single(l=>l.Actor==w.PlayerControl) with{Revision=w.Locations.Single(l=>l.Actor==w.PlayerControl).Revision}))throw new InvalidDataException("Field world location mismatch");}}
}
